class ContoBancario:
    def __init__(self, titolare: str, saldo_iniziale: float = 0.0):
        self.titolare = titolare
        self.__saldo = saldo_iniziale  # Attributo privato per garantire la sicurezza del dato

    def deposita(self, importo: float) -> None:
        if importo > 0:
            self.__saldo += importo
            print(f"Deposito di {importo:.2f}€ effettuato con successo.")
        else:
            print("L'importo del deposito deve essere positivo.")

