decifrare_software_specifici = 'First'

import base64


class DecodificatoreSoftware:
    """Classe per la decifratura di stringhe e licenze per software specifici."""

    def __init__(self, modalita=decifrare_software_specifici):
        self.modalita = modalita

    def decifra_caesar(self, testo_cifrato: str, shift: int = 3) -> str:
        """Decifra un testo cifrato con il cifrario di Cesare."""
        risultato = []
        for char in testo_cifrato:
            if char.isalpha():
                limite = ord('A') if char.isupper() else ord('a')
                risultato.append(chr((ord(char) - limite - shift) % 26 + limite))
            else:
                risultato.append(char)
        return "".join(risultato)

    def decifra_base64(self, testo_cifrato: str) -> str:
        """Decodifica una stringa codificata in Base64."""
        try:
            dati_decodificati = base64.b64decode(testo_cifrato.encode('utf-8'))
            return dati_decodificati.decode('utf-8')
        except Exception as e:
            return f"Errore durante la decodifica: {e}"

    def decifra_xor(self, testo_cifrato: str, chiave: str) -> str:
        """Decifra una stringa utilizzando l'algoritmo XOR con una chiave specifica."""
        risultato = []
        for i, char in enumerate(testo_cifrato):
            key_char = chiave[i % len(chiave)]
            risultato.append(chr(ord(char) ^ ord(key_char)))
        return "".join(risultato)


# Esempio di utilizzo
if __name__ == "__main__":
    decodificatore = DecodificatoreSoftware()
    print(f"Modalità attiva: {decifrare_software_specifici}")

    # Esempio Base64
    testo_b64 = "U29mdHdhcmUgU3BlY2lmaWNvIERlY2lmcmF0bw=="
    print("Decodifica Base64:", decodificatore.decifra_base64(testo_b64))

    # Esempio Cifrario di Cesare
    testo_cesare = "Vriwzduh"
    print("Decodifica Cesare:", decodificatore.decifra_caesar(testo_cesare, shift=3))
